def transform(grid):
    h, w = len(grid), len(grid[0])

    # The object is a regular lattice. Find its divider rows and columns
    # by looking for repeated runs of a color distinct from the tile fill.
    row_candidates = []
    for r in range(h):
        if sum(v == grid[r][0] for v in grid[r]) >= w - 2:
            row_candidates.append(r)

    col_candidates = []
    for c in range(w):
        if sum(grid[r][c] == grid[0][c] for r in range(h)) >= h - 2:
            col_candidates.append(c)

    # Estimate the lattice periods from the repeating background.
    def period(seq):
        for p in range(2, len(seq) + 1):
            if all(seq[i] == seq[i % p] for i in range(len(seq))):
                return p
        return 1

    rp = period([row[:] for row in grid])
    cp = period([tuple(grid[r][c] for r in range(h)) for c in range(w)])

    # Divider rows/columns are the regularly spaced bands. Their crossings
    # carry the encoded colors; replace ordinary frame/background colors
    # with the tile's interior color.
    if len(row_candidates) >= 2:
        rstep = min(b - a for a, b in zip(row_candidates, row_candidates[1:]))
        rows = row_candidates[::max(1, row_candidates[1] - row_candidates[0] and 1)]
        rows = [r for r in row_candidates if r % rstep == row_candidates[0] % rstep]
    else:
        rows = list(range(0, h, max(1, rp)))

    if len(col_candidates) >= 2:
        cstep = min(b - a for a, b in zip(col_candidates, col_candidates[1:]))
        cols = [c for c in col_candidates if c % cstep == col_candidates[0] % cstep]
    else:
        cols = list(range(0, w, max(1, cp)))

    # A crossing-grid output is read one interval inside each divider.
    if len(rows) > 1:
        rows = rows[:-1]
    if len(cols) > 1 and cols[0] == 0:
        cols = cols[1:]

    fill = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = []
    for r in rows:
        line = []
        for c in cols:
            v = grid[r][c]
            line.append(v if v not in (grid[r][0], grid[0][c]) else fill)
        if line:
            out.append(line)
    return out if out else [[grid[0][0]]]
